 return `<div class="mountSummary"><div class="mountSummaryHead"><span>Quelle (Host / Volume)</span><span></span><span>Im Container</span></div>${items.map((x)=>{const volume=x.Type==='volume',source=volume?(x.Name||x.Source||'–'):(x.Source||'–');return `<div class="mountSummaryRow"><span class="mountSource"><code>${esc(source)}</code></span><span class="mountArrow">→</span><span class="mountTarget"><code>${esc(x.Destination||'–')}</code>${x.RW===false?'<i class="mountRO">RO</i>':''}</span></div>`}).join('')}</div>`;
